public enum VodDemoWork: String, Identifiable, CaseIterable, Sendable {
    case series, movie, longVideo, incompatible

    public static let isEnabled = VodDemoSandbox.isEnabled
    public static let sources: [VodPlaybackSource] = [
        VodPlaybackSource(id: "source-a", title: "线路一"),
        VodPlaybackSource(id: "source-b", title: "线路二")
    ]

    public var id: String { rawValue }
    public var title: String {
        switch self {
        case .series: "雾港回声"
        case .movie: "远山来信"
        case .longVideo: "海岬列车"
        case .incompatible: "协议不兼容示例"
        }
    }

    public var categoryTitle: String {
        switch self {
        case .series: "剧集"
        case .movie: "电影"
        case .longVideo: "剧集"
        case .incompatible: "协议诊断"
        }
    }

    public var synopsis: String {
        switch self {
        case .series: "一场海雾，把多年未归的人重新带回港口。"
        case .movie: "一封寄自山间的信，让两位旧友踏上重逢的旅程。"
        case .longVideo: "直达横屏"
        case .incompatible: "查看插件未提供受支持的点播能力时的提示。"
        }
    }

    public var featuredImage: CGImage? {
        switch self {
        case .series, .longVideo: DemoArtwork.seriesImage
        case .movie: DemoArtwork.movieImage
        case .incompatible: nil
        }
    }

    public var pluginID: String {
        switch self {
        case .series, .movie: VodDemoSandbox.pluginID
        case .longVideo: VodDemoSandbox.longVideoPluginID
        case .incompatible: VodDemoSandbox.unsupportedPluginID
        }
    }

    private var liveType: LiveType { LiveType(stringLiteral: pluginID) }

    public var room: LiveModel {
        LiveModel(userName: "", roomTitle: title, roomCover: "", userHeadImg: "", liveType: liveType,
                  liveState: nil, userId: "", roomId: id, liveWatchedCount: nil)
    }

    public static func matching(_ room: LiveModel) -> Self? {
        guard isEnabled, let work = Self(rawValue: room.roomId), room.liveType.rawValue == work.pluginID else { return nil }
        return work
    }

    public static var launchWork: Self {
        let args = ProcessInfo.processInfo.arguments
        guard let index = args.firstIndex(of: "-AngelLiveVodDemoWork"),
              let name = args.dropFirst(index + 1).first else { return .series }
        return Self(rawValue: name) ?? .series
    }

    @MainActor
    public func makeModel(progressStore: VodProgressStore) -> VodPlaybackModel {
        if self == .longVideo,
           let sandbox = try? VodDemoSandbox.current.get(),
           let plugin = try? sandbox.pluginManager.resolve(pluginId: pluginID),
           VodPluginPolicy.isLongVideoSupported(plugin.manifest) {
            let source = VodLongVideoSource(room: room, plugin: plugin, pluginManager: sandbox.pluginManager) {
                let media = try await VodDemoMedia.shared.prepare()
                return ["sampleURL": media.directory.appendingPathComponent("sample.mp4").absoluteString]
            }
            return VodPlaybackModel(dependencies: source.dependencies, progressStore: progressStore)
        }
        return VodPlaybackModel(dependencies: .init(
            loadDetail: {
                guard self == .series || self == .movie else { throw VodCatalogError.unsupportedPlugin }
                let media = try await VodDemoMedia.shared.prepare()
                return detail(media: media)
            },
            resolvePlayback: { detail, episode, sourceID in
                guard self == .series || self == .movie else { throw VodCatalogError.unsupportedPlugin }
                let media = try await VodDemoMedia.shared.prepare()
                let url = media.directory.appendingPathComponent("sample.mp4")
                let subtitles = VodSubtitleFormat.allCases.map {
                    VodExternalSubtitle(subtitleID: $0.rawValue, name: "演示字幕 \($0.rawValue.uppercased())",
                                        language: "zh", format: $0,
                                        url: media.directory.appendingPathComponent("sample.\($0.rawValue)"))
                }
                let json = """
                {"isLive":false,"url":"\(url.absoluteString)"}
                """
                let parsed = try VodCatalog.playback(from: Data(json.utf8), workID: detail.workID, episode: episode,
                                                     liveType: liveType)
                return VodResolvedPlayback(
                    workID: detail.workID, episodeID: episode.id, rawEpisodeID: episode.episodeID,
                    sourceID: sourceID ?? Self.sources.first?.id, sources: Self.sources,
                    url: url, quality: parsed.quality, subtitles: subtitles,
                    introMarker: self == .series ? .init(kind: .intro, start: 0, end: 8) : nil,
                    creditsMarker: self == .series ? .init(kind: .credits, start: 50, end: 60) : nil
                )
            }
        ), progressStore: progressStore)
    }

    private static let firstSeason: [(title: String, synopsis: String)] = [
        ("末班渡船", "阿岑赶上停航前的最后一班船，父亲留下的提灯却已有人点亮。"),
        ("空船归港", "一艘无人认领的渔船随潮进港，船舱里还晾着她小时候的雨衣。"),
        ("灯下海图", "修灯人揭开旧海图的一角，背面记着一串与航道无关的日期。"),
        ("逆流的纸船", "卖鱼女孩把纸船放进排水沟，带阿岑找到了被石阶封住的旧水门。"),
        ("崖上的车灯", "天亮前两束车灯停在海崖边，司机交给她一卷受潮的录音带。"),
        ("少一束光", "阿岑整夜数着塔灯，终于听清录音里那句藏在第三次停顿中的呼喊。"),
        ("寄存处", "渡口清退无人领取的行李，一只藤箱的钥匙恰好挂在父亲的灯柄上。"),
        ("船底的名字", "老船匠刮去藤箱木板上的黑漆，认出那是从一艘旧救生艇上拆下的。"),
        ("迟到的潮汐表", "寄往灯塔的信晚了十九年，信里的潮汐表比港务所的记录早了一小时。"),
        ("退潮时分", "海水从石阶退尽，阿岑第一次走到了童年照片中那扇蓝门前。"),
        ("借宿的人", "蓝门里住着一位失明的报务员，他凭脚步声把阿岑错认成了母亲。"),
        ("静默频道", "修好的短波机收到三声敲击，报务员坚持要等到次日同一刻再回话。"),
        ("雨棚下的座位", "避雨的旧船员围坐一桌，直到女孩多摆了一副碗筷才有人肯讲那一夜。"),
        ("雾线以外", "阿岑随船驶过禁航浮标，在另一侧岛岸看见一排仍有人修补的渔网。"),
        ("两本值班簿", "岛上塔楼留着另一本值班簿，同一处涂改下竟是两个不同的签名。"),
        ("水门重开", "暴雨淹没低街，阿岑必须在保住旧信和打开水门之间作出选择。"),
        ("回程票", "山口司机翻出夹在遮阳板后的渡船票，承认自己当年接走过一个孩子。"),
        ("灯罩的裂纹", "换下的灯罩在墙上投出双影，让所有人记错的第二座灯塔有了解释。"),
        ("潮音室", "阿岑在废弃广播室接通旧话筒，邀请当年的乘客留下各自听见的最后一句话。"),
        ("最后一网", "老船匠将封存多年的渔网抛进雾湾，这次等在船尾的是整条街的人。"),
        ("未寄出的回信", "阿岑拼好从网中捞起的铁盒，读到了母亲写给每一户人家的回信。"),
        ("港口晨钟", "复航那天，阿岑把父亲的灯交到新船长手里，自己留在岸上敲响晨钟。")
    ]

    private static let secondSeason: [(title: String, synopsis: String)] = [
        ("冬日里程碑", "入冬后的第一辆邮车带来一张山路照片，照片背面约她去见当年的孩子。"),
        ("对岸有灯", "海峡两端的灯同时亮起，阿岑终于把那盒回信交给了最后一位收信人。")
    ]

    private func detail(media: VodDemoMedia.Files) -> VodWorkDetail {
        let first = VodSeason(id: "season-a", number: 1, title: "第一季")
        let second = VodSeason(id: "season-b", number: 2, title: "第二季")
        let seasons = self == .series ? [first, second] : [
            VodSeason(id: VodCatalog.movieSeasonID, number: 1, title: "电影")
        ]
        let stories = self == .series ? [Self.firstSeason, Self.secondSeason]
            : [[(title: title, synopsis: "末班车开走后，两个循信而来的人在山间小站认出了彼此的笔迹。")]]
        let episodes = zip(seasons, stories).flatMap { season, stories in
            stories.enumerated().map { index, story in
                let number = index + 1
                let still = self == .movie ? 2 : (index + (season == second ? Self.firstSeason.count : 0)) % 6 + 1
                return VodEpisode(
                    pluginID: pluginID, workID: id, episodeID: "\(season.id)-episode-\(number)",
                    seasonID: season.id, number: number, title: story.title, durationHint: 60,
                    stillURL: media.directory.appendingPathComponent("still-\(still).jpg").absoluteString,
                    synopsis: story.synopsis
                )
            }
        }
        return VodWorkDetail(
            pluginID: pluginID, workID: id, title: title, kind: self == .series ? .series : .movie,
            synopsis: synopsis,
            posterURL: media.directory.appendingPathComponent("\(id).jpg").absoluteString,
            backdropURL: media.directory.appendingPathComponent("\(id)-hero.jpg").absoluteString,
            year: 2026, seasons: seasons, hasExplicitSeasons: self == .series, episodes: episodes
        )
    }
}

public actor VodDemoMedia {
    public static let shared = VodDemoMedia()

    public struct Files: Sendable {
        public let directory: URL
    }

    private var files: Files?

    public func prepare() async throws -> Files {
        if let files { return files }
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        let generated = try await DemoWriter.generate(in: directory)
        files = generated
        return generated
    }
}

nonisolated private enum DemoWriter {
    private enum MediaError: Error { case writer, sample, artwork }
    private static let frameRate: Int32 = 24
    private static let duration: Int = 60
    private static let sampleRate = 24_000
    private static let width = 480
    private static let height = 270

    @concurrent
    static func generate(in directory: URL) async throws -> VodDemoMedia.Files {
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        do {
            let stills = try writeArtwork(in: directory)
            try await video(at: directory.appendingPathComponent("sample.mp4"), stills: stills)
            try writeSubtitles(in: directory)
            return .init(directory: directory)
        } catch {
            try? FileManager.default.removeItem(at: directory)
            throw error
        }
    }

    private static func video(at url: URL, stills: [CGImage]) async throws {
        let writer = try AVAssetWriter(outputURL: url, fileType: .mp4)
        let video = AVAssetWriterInput(mediaType: .video, outputSettings: [
            AVVideoCodecKey: AVVideoCodecType.h264,
            AVVideoWidthKey: width,
            AVVideoHeightKey: height,
            AVVideoCompressionPropertiesKey: [
                AVVideoAverageBitRateKey: 1_200_000,
                AVVideoExpectedSourceFrameRateKey: frameRate,
                AVVideoMaxKeyFrameIntervalKey: frameRate * 2,
                AVVideoAllowFrameReorderingKey: false
            ]
        ])
        let pixels = AVAssetWriterInputPixelBufferAdaptor(assetWriterInput: video, sourcePixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferWidthKey as String: width,
            kCVPixelBufferHeightKey as String: height,
            kCVPixelBufferCGImageCompatibilityKey as String: true,
            kCVPixelBufferCGBitmapContextCompatibilityKey as String: true
        ])
        let aac: [String: Any] = [
            AVFormatIDKey: kAudioFormatMPEG4AAC, AVSampleRateKey: sampleRate,
            AVNumberOfChannelsKey: 1, AVEncoderBitRateKey: 64_000
        ]
        let audio = [
            AVAssetWriterInput(mediaType: .audio, outputSettings: aac),
            AVAssetWriterInput(mediaType: .audio, outputSettings: aac)
        ]
        audio[0].extendedLanguageTag = "zh"
        audio[1].extendedLanguageTag = "en"
        let audioFormat = try pcmFormat()
        let subtitleFormat = try textFormat()
        let subtitles = AVAssetWriterInput(mediaType: .subtitle, outputSettings: nil, sourceFormatHint: subtitleFormat)
        subtitles.extendedLanguageTag = "zh"
        let inputs = [video] + audio + [subtitles]
        for input in inputs {
            guard writer.canAdd(input) else { throw MediaError.writer }
            writer.add(input)
        }
        guard writer.startWriting() else { throw writer.error ?? MediaError.writer }
        writer.startSession(atSourceTime: .zero)

        do {
            guard let pool = pixels.pixelBufferPool else { throw MediaError.writer }
            let cue = try textSample("内嵌字幕 · 演示", at: 0, duration: duration, format: subtitleFormat)
            let frameCount = duration * Int(frameRate)
            var videoFrame = 0
            var audioFrames = Array(repeating: 0, count: audio.count)
            var wroteSubtitle = false
            while videoFrame < frameCount || audioFrames.contains(where: { $0 < frameCount }) || !wroteSubtitle {
                try Task.checkCancellation()
                guard writer.status == .writing else { throw writer.error ?? MediaError.writer }
                // The writer interleaves tracks. A temporarily blocked input must
                // let the other inputs advance before it can accept more data.
                var wroteSample = false
                if !wroteSubtitle && subtitles.isReadyForMoreMediaData {
                    guard subtitles.append(cue) else { throw writer.error ?? MediaError.writer }
                    subtitles.markAsFinished()
                    wroteSubtitle = true
                    wroteSample = true
                }
                if videoFrame < frameCount && video.isReadyForMoreMediaData {
                    let pixel = try frameBuffer(pool: pool, frame: videoFrame, stills: stills)
                    let time = CMTime(value: Int64(videoFrame), timescale: frameRate)
                    guard pixels.append(pixel, withPresentationTime: time) else { throw writer.error ?? MediaError.writer }
                    videoFrame += 1
                    if videoFrame == frameCount { video.markAsFinished() }
                    wroteSample = true
                }
                for (index, input) in audio.enumerated()
                    where audioFrames[index] < frameCount && input.isReadyForMoreMediaData {
                    let sample = try audioSample(frame: audioFrames[index], frequency: index == 0 ? 220 : 330,
                                                 format: audioFormat)
                    guard input.append(sample) else { throw writer.error ?? MediaError.writer }
                    audioFrames[index] += 1
                    if audioFrames[index] == frameCount { input.markAsFinished() }
                    wroteSample = true
                }
                if !wroteSample { try await Task.sleep(for: .milliseconds(3)) }
            }
            writer.endSession(atSourceTime: CMTime(value: Int64(duration), timescale: 1))
            await writer.finishWriting()
            guard writer.status == .completed else { throw writer.error ?? MediaError.writer }
        } catch {
            writer.cancelWriting()
            throw error
        }
    }

    private static func frameBuffer(pool: CVPixelBufferPool, frame: Int, stills: [CGImage]) throws -> CVPixelBuffer {
        var result: CVPixelBuffer?
        guard CVPixelBufferPoolCreatePixelBuffer(nil, pool, &result) == kCVReturnSuccess, let pixel = result,
              CVPixelBufferLockBaseAddress(pixel, []) == kCVReturnSuccess else { throw MediaError.sample }
        defer { CVPixelBufferUnlockBaseAddress(pixel, []) }
        guard let context = CGContext(
            data: CVPixelBufferGetBaseAddress(pixel), width: width, height: height, bitsPerComponent: 8,
            bytesPerRow: CVPixelBufferGetBytesPerRow(pixel), space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGBitmapInfo.byteOrder32Little.rawValue | CGImageAlphaInfo.premultipliedFirst.rawValue
        ) else { throw MediaError.sample }
        let shotLength = duration * Int(frameRate) / stills.count
        let shot = frame / shotLength
        let progress = CGFloat(frame % shotLength) / CGFloat(shotLength - 1)
        let eased = progress * progress * (3 - 2 * progress)
        let travel = shot.isMultiple(of: 2) ? eased : 1 - eased
        let scale = 1.02 + 0.08 * travel
        let w = CGFloat(width), h = CGFloat(height)
        let rect = CGRect(x: -w * (scale - 1) * (0.3 + 0.4 * eased),
                          y: -h * (scale - 1) * 0.5, width: w * scale, height: h * scale)
        context.interpolationQuality = .high
        context.draw(stills[shot], in: rect)
        return pixel
    }

    private static func pcmFormat() throws -> CMAudioFormatDescription {
        var stream = AudioStreamBasicDescription(
            mSampleRate: Double(sampleRate), mFormatID: kAudioFormatLinearPCM,
            mFormatFlags: kAudioFormatFlagIsFloat | kAudioFormatFlagIsPacked,
            mBytesPerPacket: 4, mFramesPerPacket: 1, mBytesPerFrame: 4,
            mChannelsPerFrame: 1, mBitsPerChannel: 32, mReserved: 0
        )
        var format: CMAudioFormatDescription?
        let status = CMAudioFormatDescriptionCreate(allocator: nil, asbd: &stream, layoutSize: 0, layout: nil,
                                                    magicCookieSize: 0, magicCookie: nil, extensions: nil,
                                                    formatDescriptionOut: &format)
        guard status == noErr, let format else { throw MediaError.sample }
        return format
    }

    private static func audioSample(frame: Int, frequency: Double, format: CMAudioFormatDescription) throws -> CMSampleBuffer {
        let count = sampleRate / Int(frameRate)
        let start = frame * count
        let samples = (0..<count).map { index -> Float in
            let t = Double(start + index) / Double(sampleRate)
            let envelope = pow(max(0, sin(t * .pi / 2)), 2)
            return Float(sin(t * frequency * 2 * .pi) * envelope * 0.035)
        }
        let buffer = try samples.withUnsafeBytes { try blockBuffer(copying: $0) }
        return try makeSample(
            buffer, format: format, count: count, bytesPerSample: MemoryLayout<Float>.size,
            start: CMTime(value: Int64(start), timescale: Int32(sampleRate)),
            duration: CMTime(value: 1, timescale: Int32(sampleRate))
        )
    }

    private static func textFormat() throws -> CMFormatDescription {
        // ISO timed-text sample description. The writer needs the default style
        // and font table to serialize an embedded subtitle track in MP4.
        let description: [UInt8] = [
            0, 0, 0, 64, 0x74, 0x78, 0x33, 0x67, // Size and tx3g format code
            0, 0, 0, 0, 0, 0, 0, 1, // Reserved bytes and data reference
            0, 0, 0, 0, 0, 255, // Display flags, centered text, bottom alignment
            0, 0, 0, 0, // Transparent background
            0, 0, 0, 0, 0, 0, 0, 0, // Default text box
            0, 0, 0, 0, 0, 1, 0, 20, 255, 255, 255, 255, // White 20pt text, font 1
            0, 0, 0, 18, 0x66, 0x74, 0x61, 0x62, // Font table size and format code
            0, 1, 0, 1, 5, 0x53, 0x65, 0x72, 0x69, 0x66 // One font: Serif
        ]
        var format: CMFormatDescription?
        let status = CMTextFormatDescriptionCreateFromBigEndianTextDescriptionData(
            allocator: nil, bigEndianTextDescriptionData: description, size: description.count,
            flavor: nil, mediaType: kCMMediaType_Subtitle, formatDescriptionOut: &format
        )
        guard status == noErr, let format else { throw MediaError.sample }
        return format
    }

    private static func textSample(_ text: String, at start: Int, duration: Int,
                                   format: CMFormatDescription) throws -> CMSampleBuffer {
        let data = Array(text.utf8)
        let bytes = [UInt8(data.count >> 8), UInt8(data.count & 255)] + data
        let buffer = try bytes.withUnsafeBytes { try blockBuffer(copying: $0) }
        return try makeSample(buffer, format: format, count: 1, bytesPerSample: bytes.count,
                              start: CMTime(value: Int64(start), timescale: 1),
                              duration: CMTime(value: Int64(duration), timescale: 1))
    }

    private static func blockBuffer(copying bytes: UnsafeRawBufferPointer) throws -> CMBlockBuffer {
        var buffer: CMBlockBuffer?
        let status = CMBlockBufferCreateWithMemoryBlock(allocator: nil, memoryBlock: nil, blockLength: bytes.count,
                                                       blockAllocator: nil, customBlockSource: nil,
                                                       offsetToData: 0, dataLength: bytes.count, flags: 0,
                                                       blockBufferOut: &buffer)
        guard status == noErr, let buffer, let base = bytes.baseAddress,
              CMBlockBufferReplaceDataBytes(with: base, blockBuffer: buffer, offsetIntoDestination: 0,
                                            dataLength: bytes.count) == noErr else { throw MediaError.sample }
        return buffer
    }

    private static func makeSample(_ block: CMBlockBuffer, format: CMFormatDescription, count: Int, bytesPerSample: Int,
                                   start: CMTime, duration: CMTime) throws -> CMSampleBuffer {
        var result: CMSampleBuffer?
        var timing = CMSampleTimingInfo(duration: duration, presentationTimeStamp: start, decodeTimeStamp: .invalid)
        var bytesPerSample = bytesPerSample
        let status = CMSampleBufferCreateReady(allocator: nil, dataBuffer: block, formatDescription: format,
                                               sampleCount: count, sampleTimingEntryCount: 1, sampleTimingArray: &timing,
                                               sampleSizeEntryCount: 1, sampleSizeArray: &bytesPerSample,
                                               sampleBufferOut: &result)
        guard status == noErr, let result else { throw MediaError.sample }
        return result
    }

    private static func writeArtwork(in directory: URL) throws -> [CGImage] {
        func write(_ encoded: String, name: String) throws -> Data {
            guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters) else {
                throw MediaError.artwork
            }
            try data.write(to: directory.appendingPathComponent(name))
            return data
        }
        _ = try write(DemoArtwork.seriesHero, name: "series-hero.jpg")
        _ = try write(DemoArtwork.movieHero, name: "movie-hero.jpg")
        _ = try write(DemoArtwork.series, name: "series.jpg")
        _ = try write(DemoArtwork.movie, name: "movie.jpg")
        return try DemoArtwork.stills.enumerated().map { index, encoded in
            let data = try write(encoded, name: "still-\(index + 1).jpg")
            guard let source = CGImageSourceCreateWithData(data as CFData, nil),
                  let image = CGImageSourceCreateImageAtIndex(source, 0, [kCGImageSourceShouldCacheImmediately: true] as CFDictionary)
            else { throw MediaError.artwork }
            return image
        }
    }

    private static func writeSubtitles(in directory: URL) throws {
        let srt = "1\n00:00:01,000 --> 00:00:59,000\n雾灯亮起 · SRT\n"
        let vtt = "WEBVTT\n\n00:00:01.000 --> 00:00:59.000\n潮声渐近 · VTT\n"
        let ass = """
        [Script Info]
        ScriptType: v4.00+
        PlayResX: 640
        PlayResY: 360
        [V4+ Styles]
        Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
        Style: Default,PingFang SC,20,&H0038D7FF,&H00FFFFFF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,1,0,2,12,12,24,1
        [Events]
        Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
        Dialogue: 0,0:00:01.00,0:00:59.00,Default,,0,0,0,,灯光照向海面 · ASS

        """
        for (name, text) in [("srt", srt), ("vtt", vtt), ("ass", ass)] {
            try text.write(to: directory.appendingPathComponent("sample.\(name)"), atomically: true, encoding: .utf8)
        }
    }
}

// JPEG originals are embedded only in the debug fixture.
nonisolated private enum DemoArtwork {
    static let seriesImage = image(from: seriesHero)
    static let movieImage = image(from: movieHero)

    private static func image(from encoded: String) -> CGImage? {
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
              let source = CGImageSourceCreateWithData(data as CFData, nil) else { return nil }
        return CGImageSourceCreateImageAtIndex(source, 0, nil)
